CREATE TABLE IF NOT EXISTS gestao_comando (chave UUID PRIMARY KEY, escopo VARCHAR(100) NOT NULL, assinatura VARCHAR(64) NOT NULL, resposta TEXT, criado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE compra_pedido ADD COLUMN IF NOT EXISTS data_vencimento DATE;
CREATE TABLE IF NOT EXISTS gestao_auditoria (id BIGSERIAL PRIMARY KEY, modulo VARCHAR(40) NOT NULL, acao VARCHAR(50) NOT NULL, entidade VARCHAR(60) NOT NULL, registro_id BIGINT, usuario_id BIGINT NOT NULL, usuario VARCHAR(150) NOT NULL, detalhe VARCHAR(500) NOT NULL, criado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_gestao_auditoria_data ON gestao_auditoria(criado_em DESC,id DESC);
CREATE TABLE IF NOT EXISTS gestao_parametro (chave VARCHAR(80) PRIMARY KEY, descricao VARCHAR(200) NOT NULL, valor INTEGER NOT NULL CHECK(valor BETWEEN 0 AND 90), versao BIGINT NOT NULL DEFAULT 0);
INSERT INTO gestao_parametro(chave,descricao,valor) VALUES ('pcp.antecedencia_dias','Dias de antecedência para destacar ordens próximas do prazo',3),('financeiro.antecedencia_dias','Dias de antecedência para destacar títulos próximos do vencimento',5) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS pcp_linha (id BIGSERIAL PRIMARY KEY, nome VARCHAR(100) NOT NULL, horas_dia NUMERIC(5,2) NOT NULL CHECK(horas_dia>0 AND horas_dia<=24), ativo BOOLEAN NOT NULL DEFAULT TRUE, versao BIGINT NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX IF NOT EXISTS uk_pcp_linha_nome ON pcp_linha(lower(nome));
CREATE TABLE IF NOT EXISTS comercial_pedido (id BIGSERIAL PRIMARY KEY, cliente VARCHAR(150) NOT NULL, produto VARCHAR(150) NOT NULL, quantidade INTEGER NOT NULL CHECK(quantidade>0 AND quantidade<=1000000000), valor_unitario NUMERIC(15,2) NOT NULL CHECK(valor_unitario>0), entrega DATE NOT NULL, vencimento DATE NOT NULL, status VARCHAR(25) NOT NULL CHECK(status IN ('RASCUNHO','CONFIRMADO','EM_PRODUCAO','PRONTO','EXPEDIDO','CANCELADO')), versao BIGINT NOT NULL DEFAULT 0, criado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pcp_ordem (id BIGSERIAL PRIMARY KEY, produto VARCHAR(150) NOT NULL, quantidade INTEGER NOT NULL CHECK(quantidade>0 AND quantidade<=1000000000), inicio DATE NOT NULL, previsao DATE NOT NULL CHECK(previsao>=inicio), responsavel VARCHAR(150) NOT NULL, linha_id BIGINT REFERENCES pcp_linha(id), horas_previstas NUMERIC(10,2) NOT NULL CHECK(horas_previstas>0), pedido_id BIGINT UNIQUE REFERENCES comercial_pedido(id), status VARCHAR(20) NOT NULL CHECK(status IN ('PLANEJADA','EM_PRODUCAO','FINALIZADA','CANCELADA')), iniciado_em TIMESTAMPTZ, concluido_em TIMESTAMPTZ, expedido_em TIMESTAMPTZ, chegada_id BIGINT REFERENCES registro_chegada(id), versao BIGINT NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS ix_pcp_ordem_programacao ON pcp_ordem(linha_id,inicio,previsao);
CREATE TABLE IF NOT EXISTS pcp_requisicao (id BIGSERIAL PRIMARY KEY, ordem_id BIGINT NOT NULL REFERENCES pcp_ordem(id), produto_id BIGINT NOT NULL REFERENCES produto(id), quantidade INTEGER NOT NULL CHECK(quantidade BETWEEN 1 AND 1000000000), motivo VARCHAR(500) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDENTE' CHECK(status IN ('PENDENTE','ATENDIDA','RECUSADA','DEVOLVIDA')), resposta VARCHAR(1000), versao BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS financeiro_titulo (id BIGSERIAL PRIMARY KEY, tipo VARCHAR(10) NOT NULL CHECK(tipo IN ('PAGAR','RECEBER')), descricao VARCHAR(200) NOT NULL, pessoa VARCHAR(150) NOT NULL, valor NUMERIC(15,2) NOT NULL CHECK(valor>0), vencimento DATE NOT NULL, documento VARCHAR(100), emissao DATE, referencia VARCHAR(150), origem VARCHAR(30) NOT NULL DEFAULT 'MANUAL', origem_id BIGINT, status VARCHAR(20) NOT NULL DEFAULT 'PENDENTE' CHECK(status IN ('PENDENTE','BAIXADO','CANCELADO')), baixa DATE, versao BIGINT NOT NULL DEFAULT 0, CHECK(baixa IS NULL OR status='BAIXADO'), UNIQUE(origem,origem_id));
CREATE UNIQUE INDEX IF NOT EXISTS uk_financeiro_documento ON financeiro_titulo(lower(pessoa),lower(documento),tipo) WHERE documento IS NOT NULL AND status<>'CANCELADO';
CREATE INDEX IF NOT EXISTS ix_financeiro_vencimento ON financeiro_titulo(tipo,vencimento);
CREATE TABLE IF NOT EXISTS compra_cotacao (id BIGSERIAL PRIMARY KEY, pedido_id BIGINT NOT NULL REFERENCES compra_pedido(id), fornecedor1 VARCHAR(150) NOT NULL, valor1 NUMERIC(15,2) NOT NULL CHECK(valor1>0), fornecedor2 VARCHAR(150), valor2 NUMERIC(15,2), fornecedor3 VARCHAR(150), valor3 NUMERIC(15,2), escolhido INTEGER CHECK(escolhido BETWEEN 1 AND 3), status VARCHAR(20) NOT NULL DEFAULT 'ABERTA' CHECK(status IN ('ABERTA','ESCOLHIDA','CANCELADA')), versao BIGINT NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX IF NOT EXISTS uk_compra_cotacao_aberta ON compra_cotacao(pedido_id) WHERE status='ABERTA';
CREATE TABLE IF NOT EXISTS rh_afastamento (id BIGSERIAL PRIMARY KEY, funcionario_id BIGINT NOT NULL REFERENCES funcionario(id), tipo VARCHAR(40) NOT NULL, inicio DATE NOT NULL, fim DATE NOT NULL CHECK(fim>=inicio), motivo VARCHAR(500) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDENTE' CHECK(status IN ('PENDENTE','APROVADO','RECUSADO','CANCELADO')), decisao VARCHAR(500), versao BIGINT NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS ix_rh_afastamento_periodo ON rh_afastamento(funcionario_id,inicio,fim);
CREATE TABLE IF NOT EXISTS rh_solicitacao (id BIGSERIAL PRIMARY KEY, funcionario_id BIGINT NOT NULL REFERENCES funcionario(id), tipo VARCHAR(60) NOT NULL, descricao VARCHAR(1000) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDENTE' CHECK(status IN ('PENDENTE','EM_ANALISE','APROVADO','RECUSADO')), resposta VARCHAR(1000), criado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, versao BIGINT NOT NULL DEFAULT 0);
